PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS hr_mobile_leave_intents(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,device_id TEXT REFERENCES mobile_sync_devices(id) ON DELETE SET NULL,employee_id TEXT NOT NULL REFERENCES hr_employees(id) ON DELETE CASCADE,leave_type_id TEXT NOT NULL REFERENCES hr_leave_types(id) ON DELETE RESTRICT,starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,days_micros INTEGER NOT NULL,reason TEXT,requested_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,client_created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','applied','rejected')),server_leave_request_id TEXT,error_message TEXT,applied_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS hr_mobile_leave_pending_idx ON hr_mobile_leave_intents(status,created_at);
CREATE TABLE IF NOT EXISTS hr_mobile_onboarding_intents(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,device_id TEXT REFERENCES mobile_sync_devices(id) ON DELETE SET NULL,task_id TEXT NOT NULL REFERENCES hr_onboarding_tasks(id) ON DELETE CASCADE,completed_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,client_completed_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','applied','rejected')),error_message TEXT,applied_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS hr_mobile_onboarding_pending_idx ON hr_mobile_onboarding_intents(status,created_at);
CREATE TABLE IF NOT EXISTS hr_mobile_change_events(id INTEGER PRIMARY KEY AUTOINCREMENT,organization_id TEXT NOT NULL,collection_key TEXT NOT NULL,record_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN ('upsert','delete')),payload_json TEXT);
CREATE TRIGGER IF NOT EXISTS hr_mobile_change_apply AFTER INSERT ON hr_mobile_change_events BEGIN
 INSERT INTO mobile_sync_record_versions(organization_id,module_key,collection_key,record_id,version,deleted,server_updated_at,last_device_id) VALUES(NEW.organization_id,'human-resources',NEW.collection_key,NEW.record_id,1,CASE WHEN NEW.operation='delete' THEN 1 ELSE 0 END,CURRENT_TIMESTAMP,NULL) ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=mobile_sync_record_versions.version+1,deleted=excluded.deleted,server_updated_at=CURRENT_TIMESTAMP,last_device_id=NULL;
 DELETE FROM mobile_sync_tombstones WHERE NEW.operation='upsert' AND organization_id=NEW.organization_id AND module_key='human-resources' AND collection_key=NEW.collection_key AND record_id=NEW.record_id;
 INSERT INTO mobile_sync_tombstones(organization_id,module_key,collection_key,record_id,version,deleted_at,device_id) SELECT NEW.organization_id,'human-resources',NEW.collection_key,NEW.record_id,v.version,CURRENT_TIMESTAMP,NULL FROM mobile_sync_record_versions v WHERE NEW.operation='delete' AND v.organization_id=NEW.organization_id AND v.module_key='human-resources' AND v.collection_key=NEW.collection_key AND v.record_id=NEW.record_id ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=excluded.version,deleted_at=CURRENT_TIMESTAMP,device_id=NULL;
 INSERT INTO mobile_sync_changes(organization_id,module_key,collection_key,record_id,version,operation,payload_json,changed_by,device_id,changed_at) SELECT NEW.organization_id,'human-resources',NEW.collection_key,NEW.record_id,v.version,NEW.operation,NEW.payload_json,NULL,NULL,CURRENT_TIMESTAMP FROM mobile_sync_record_versions v WHERE v.organization_id=NEW.organization_id AND v.module_key='human-resources' AND v.collection_key=NEW.collection_key AND v.record_id=NEW.record_id;
 DELETE FROM hr_mobile_change_events WHERE id=NEW.id;
END;
CREATE TRIGGER IF NOT EXISTS hr_sync_employee_insert AFTER INSERT ON hr_employees BEGIN INSERT INTO hr_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'employees',NEW.id,'upsert',json_object('id',NEW.id,'employeeNumber',NEW.employee_number,'departmentId',NEW.department_id,'jobTitle',NEW.job_title,'employmentType',NEW.employment_type,'employmentStatus',NEW.employment_status,'hireDate',NEW.hire_date,'terminationDate',NEW.termination_date,'managerEmployeeId',NEW.manager_employee_id,'workEmail',NEW.work_email,'workPhone',NEW.work_phone)); END;
CREATE TRIGGER IF NOT EXISTS hr_sync_employee_update AFTER UPDATE ON hr_employees BEGIN INSERT INTO hr_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'employees',NEW.id,'upsert',json_object('id',NEW.id,'employeeNumber',NEW.employee_number,'departmentId',NEW.department_id,'jobTitle',NEW.job_title,'employmentType',NEW.employment_type,'employmentStatus',NEW.employment_status,'hireDate',NEW.hire_date,'terminationDate',NEW.termination_date,'managerEmployeeId',NEW.manager_employee_id,'workEmail',NEW.work_email,'workPhone',NEW.work_phone)); END;
CREATE TRIGGER IF NOT EXISTS hr_sync_employee_delete AFTER DELETE ON hr_employees BEGIN INSERT INTO hr_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(OLD.organization_id,'employees',OLD.id,'delete',NULL); END;
