CREATE TRIGGER IF NOT EXISTS hr_sync_department_delete AFTER DELETE ON hr_departments BEGIN INSERT INTO hr_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(OLD.organization_id,'departments',OLD.id,'delete',NULL); END;
CREATE TRIGGER IF NOT EXISTS hr_sync_leave_type_insert AFTER INSERT ON hr_leave_types BEGIN INSERT INTO hr_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'leave-types',NEW.id,'upsert',json_object('id',NEW.id,'code',NEW.code,'name',NEW.name,'paid',NEW.paid,'annualDays',NEW.annual_days_micros/1000000.0,'active',NEW.active)); END;
CREATE TRIGGER IF NOT EXISTS hr_sync_leave_type_update AFTER UPDATE ON hr_leave_types BEGIN INSERT INTO hr_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'leave-types',NEW.id,'upsert',json_object('id',NEW.id,'code',NEW.code,'name',NEW.name,'paid',NEW.paid,'annualDays',NEW.annual_days_micros/1000000.0,'active',NEW.active)); END;
