CREATE TRIGGER IF NOT EXISTS hr_sync_leave_update AFTER UPDATE ON hr_leave_requests BEGIN INSERT INTO hr_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'leave-requests',NEW.id,'upsert',json_object('id',NEW.id,'employeeId',NEW.employee_id,'leaveTypeId',NEW.leave_type_id,'startsOn',NEW.starts_on,'endsOn',NEW.ends_on,'days',NEW.days_micros/1000000.0,'reason',NEW.reason,'status',NEW.status,'requestedBy',NEW.requested_by,'reviewedBy',NEW.reviewed_by,'reviewedAt',NEW.reviewed_at,'reviewNotes',NEW.review_notes,'createdAt',NEW.created_at,'updatedAt',NEW.updated_at)); END;
