CREATE TRIGGER IF NOT EXISTS hr_sync_onboarding_update AFTER UPDATE ON hr_onboarding_tasks BEGIN INSERT INTO hr_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(NEW.organization_id,'onboarding-tasks',NEW.id,'upsert',json_object('id',NEW.id,'employeeId',NEW.employee_id,'title',NEW.title,'dueDate',NEW.due_date,'status',NEW.status,'assignedUserId',NEW.assigned_user_id,'completedAt',NEW.completed_at,'createdAt',NEW.created_at,'updatedAt',NEW.updated_at)); END;
